ST.xhtml:p:
R_Trigger(CLK := bFRelEnable OR g_biRelativeEnable OR g_bFixedRelExecute);
F_Trigger(CLK := bFRelEnable OR g_biRelativeClose OR g_bFixedRelExecute);

IF R_Trigger.Q THEN
  bFReltiveDone := FALSE;
  g_bFixedRelDone := FALSE;
  g_boRelativeDone := FALSE;
  IF g_biRelativeEnable THEN
    dFRelTarget := g_FAxis.NCTOPLC.ActPos + g_fiRelativeDis;
    dTargetVel := g_fiRelVelocity;
  ElSIF bFRelEnable THEN
    dFRelTarget := g_FAxis.NCTOPLC.ActPos + dFRelDistance;
    IF g_bFastInch=0 THEN
      dTargetVel := dFAxisSlowVel;
    ELSE
      dTargetVel := dFAxisFastVel;
    END_IF;
  ELSIF g_bFixedRelExecute THEN
    dFRelTarget := g_FAxis.NCTOPLC.ActPos + g_dFixedRelPos;
    dTargetVel := g_dRelVelocity;
  END_IF;

  IF dTargetVel = 0.0 THEN
    dTargetVel := g_dRelVelocity;
  END_IF;
  nFRelSwitch := 1;
  bCloseFlag := FALSE;
  bFRelEnable := FALSE;
END_IF;

IF F_Trigger.Q THEN
  bCloseFlag := TRUE;
END_IF;

IF bCloseFlag THEN
  bFReltiveDone := FALSE;
  g_bFixedRelDone := FALSE;
  g_boRelativeDone := FALSE;
  bCloseFlag := FALSE;
END_IF;

CASE nFRelSwitch OF
  0:
  nFRelSwitch := 0;
  1:
  g_FRelative.Execute := true;
  g_FRelative.Distance := dFRelTarget - g_FAxis.NCTOPLC.ActPos;
  g_FRelative.Velocity := dTargetVel;
  IF g_FRelative.Done THEN
    g_FRelative.Execute := false;
    bFReltiveDone := true;
    g_bFixedRelDone := true;
    g_boRelativeDone := true;
    nFRelSwitch := 0;
  END_IF;

  IF g_FRelative.CommandAborted OR g_FRelative.Error THEN
    g_FRelative.Execute := false;
    nFRelSwitch := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nFRelSwitch := 10;
  END_IF;
  10:
  g_FRelative.Execute := false;
  g_FPause.Execute := true;
  IF g_FPause.Done AND g_bPlcStartBuffer THEN
    g_FPause.Execute := false;
    nFRelSwitch := 1;
  END_IF;

  IF g_FPause.CommandAborted OR g_FPause.Error THEN
    g_FPause.Execute := false;
    nFRelSwitch := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nFRelSwitch := 0;
  g_FPause.Execute := false;
  g_FRelative.Execute := false;
END_IF;
